<template><div class="flex min-h-screen items-center justify-center bg-primary-950 p-4"><form class="w-full max-w-md rounded-2xl bg-white p-7 shadow-2xl" @submit.prevent="login"><p class="text-sm font-semibold uppercase tracking-wider text-primary-700">Lexshield Admin</p><h1 class="mt-2 text-3xl">Sign in</h1><p class="mt-2 text-sm text-neutral-600">Use an authorised administrator account.</p><div class="mt-7 space-y-5"><div><label class="label">Email</label><input v-model="email" class="input" type="email" required /></div><div><label class="label">Password</label><input v-model="password" class="input" type="password" required /></div><p v-if="error" class="rounded-lg bg-error-50 p-3 text-sm text-error-800">{{error}}</p><button class="btn-primary w-full" :disabled="busy">{{busy?'Signing in…':'Sign in'}}</button></div></form></div></template>
<script setup lang="ts">definePageMeta({layout:false});const route=useRoute(),email=ref(''),password=ref(''),error=ref(''),busy=ref(false);async function login(){busy.value=true;error.value='';try{const{error:e}=await useSupabase().auth.signInWithPassword({email:email.value,password:password.value});if(e)throw e;await navigateTo(String(route.query.redirect||'/admin'))}catch(e:any){error.value=e.message||'Sign-in failed'}finally{busy.value=false}}useSeoMeta({title:'Admin Sign In',robots:'noindex,nofollow'})</script>
